/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

Boolean notify_send( Notify nf , ... )
{	
	Notify_Msg* msg = (Notify_Msg *)q_remove( notify_q_free , 100 );
	
	va_list args ;   	

	if( msg )
	{
		msg->nf = nf ; 
		
		va_start( args , nf );
		{	
			msg->pld = va_arg(args,VARG) ;        
		}
		va_end( args );
		
		q_insert( notify_q_pennding , (Q_Msg*)msg );
	}	

	return !!msg ; 
}

